{"command": "python3 -c "
import json
from docx import Document
from pptx import Presentation
from openpyxl import load_workbook

R = json.load(open('output/analysis_results.json'))
key = {
 'vac%': f\"{R['city']['vac_rate']:.2f}%\", 'OT\$': f\"{R['city']['ot_cost']:,.0f}\",
 'OT%': f\"{R['city']['ot_pct']:.2f}%\", 'avg days': f\"{R['a311']['avg_res']:.2f}\",
 'A y1': f\"{R['A']['y1_net']:,.0f}\", 'B y1': f\"{R['B']['y1_net']:,.0f}\", 'H y1': f\"{R['H']['y1_net']:,.0f}\",
 'A cum': f\"{R['A']['cum3yr']:,.0f}\", 'B cum': f\"{R['B']['cum3yr']:,.0f}\", 'H cum': f\"{R['H']['cum3yr']:,.0f}\",
 'scores': (R['scores']['A'], R['scores']['B'], R['scores']['H']),
 'fte': (R['A']['fte_reallocated'], R['B']['fte_reallocated'], R['H']['fte_reallocated']),
 'sla': (R['A']['sla_gain_pp'], R['B']['sla_gain_pp'], R['H']['sla_gain_pp']),
}
print('KEY FIGURES FROM JSON:'); [print(' ', k, v) for k, v in key.items()]

def txt_docx():
    d = Document('output/Greenfield_Decision_Briefing_Memo.docx')
    t = [p.text for p in d.paragraphs]
    for tb in d.tables:
        for r in tb.rows: t.append(' '.join(c.text for c in r.cells))
    return ' '.join(t)
def txt_pptx():
    p = Presentation('output/Greenfield_Council_Presentation.pptx')
    t = []
    for s in p.slides:
        for sh in s.shapes:
            if sh.has_text_frame: t.append(sh.text_frame.text)
            if sh.has_table:
                for r in sh.table.rows: t.append(' '.join(c.text for c in r.cells))
    return ' '.join(t)
def txt_xlsx():
    wb = load_workbook('output/Greenfield_CostBenefit_Analysis.xlsx')
    return ' '.join(str(c.value) for ws in wb for row in ws.iter_rows() for c in row if c.value is not None)

memo, deck, wb = txt_docx(), txt_pptx(), txt_xlsx()
checks = [('9.06%','vac'),('4,354,518','OT\$'),('9.59%','OT%'),('10.79','days'),
          ('205,434','A y1'),('89,552','H y1'),('1,972,829','A cum'),('532,764','B cum'),('1,580,028','H cum'),
          ('3.2','scoreA'),('3.4','scoreB'),('3.6','scoreH')]
for name, blob in [('MEMO', memo), ('DECK', deck), ('WORKBOOK', wb)]:
    missing = [lbl for pat, lbl in checks if pat not in blob]
    print(f'{name}: {\"ALL KEY FIGURES PRESENT\" if not missing else \"MISSING: \" + str(missing)}')
print('memo words:', len(memo.split()), '| deck slides:', len(Presentation('output/Greenfield_Council_Presentation.pptx').slides), '| wb tabs:', load_workbook('output/Greenfield_CostBenefit_Analysis.xlsx').sheetnames)
"", "description": "Cross-verify key figures across all three deliverables", "workdir": "/work"}

{"command": "python3 -c "
from pptx import Presentation
from pptx.util import Emu
p = Presentation('/work/output/Greenfield_Council_Presentation.pptx')
print('slides:', len(p.slides))
for i, s in enumerate(p.slides, 1):
    charts = sum(1 for sh in s.shapes if sh.has_chart)
    tables = sum(1 for sh in s.shapes if sh.has_table)
    texts = []
    for sh in s.shapes:
        if sh.has_text_frame and sh.text_frame.text.strip():
            texts.append(sh.text_frame.text.strip().split('\n')[0][:60])
    print(f'{i:2d} charts={charts} tables={tables} | ' + ' | '.join(texts[:3]))
    # overflow check: shapes outside slide bounds
    for sh in s.shapes:
        r = sh.left + sh.width; b = sh.top + sh.height
        if sh.left < 0 or sh.top < 0 or r > p.slide_width + 10000 or b > p.slide_height + 10000:
            print('   OVERFLOW:', sh.shape_type, sh.left, sh.top, r, b)
"", "description": "Inspect slide count, charts, tables, overflow", "workdir": "/work"}

